rule.definition:
if(
  and(
    not(isusermemberofgroups(
      loggedInUser(),
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922"
      )
    ),
    ri!taskId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4577779",
    or(
      ri!previousTaskId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578065",
      tointeger(ri!previousTaskId) = 0,
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!previousTaskId)
    )
    /* when not a DPP Editor and nomination is new or in dpp review */
  ),
  #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4733738",
  if(
    ri!taskId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4489118",
    #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4733750",
    if(
      /*When  Inspections review is requested*/
      ri!taskId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4494074",
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4734194",
      if(
        /*When HR review completed by HR*/
        and(
          ri!previousTaskId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4489118",
          ri!taskId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4577779",
          isusermemberofgroups(
            loggedInUser(),
            #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12645233"
          )
        ),
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4733770",
        if(
          /*When Inspection Review is completed*/
          and(
            ri!previousTaskId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4494074",
            ri!taskId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4577779",
            isusermemberofgroups(
              loggedInUser(),
              #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4519640"
            )
          ),
          #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4734200",
          if(
            /*When Office visit availability requested*/
            ri!taskId = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458932",
            #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4719036",
            if(
              /*When Office visit availability completed*/
              and(
                ri!previousTaskId = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458932",
                ri!taskId = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458947"
              ),
              #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4733519",
              if(
                /*When interview availability requested*/
                ri!taskId = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458889",
                #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4733549",
                if(
                  /*When interview availability completed*/
                  and(
                    ri!previousTaskId = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458889",
                    ri!taskId = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458895"
                  ),
                  #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4733605",
                  if(
                    /* When incorrect Nomination is updated by DPP  */
                    and(
                      property(ri!nomination,"isReapprovedByBU",toboolean(null)) = true,
                      ri!taskId=#"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4183431",                      
                    ),
                    #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4753896",
                    if(
                      and(
                        property(ri!nomination,"isOpsAdditionalVettingReq",toboolean(null)) = true,
                        tointeger(ri!taskId)=#"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4183431"                    
                      ),
                      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5022410",
                      if(
                        and(
                          /*Add is vetting requested condition*/
                          toboolean(ri!isAdditionalFollowUpReq)=true,
                          ri!taskId=#"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578617",
                          property(ri!nomination,"isOpsAdditionalVettingReqCompleted",toboolean(null)) = true,
                        ),
                        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4985423",
                        if(
                          and(
                            not(property(ri!nomination,"isOpsAdditionalVettingReq",toboolean(null)) = true),
                            tointeger(ri!taskId)=#"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4183431" 
                          ),
                          #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5046131",
                          if(
                            ri!taskId=#"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578617",
                            #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5046137",
                            if(
                              ri!taskId=#"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4577792",
                              #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12459354",
                              null
                            )
                          )
                        )
                      )   
                    )
                  )
                )
              )
            )
          )
        )
      )
    )
  )
)
